```ts
export interface RevenueLineItem {
  unitPriceCents: number;
  quantity: number;
  discountCents?: number;
}

export interface StandardRevenueInput {
  items: RevenueLineItem[];
  taxRateBps?: number; // basis points, e.g. 750 = 7.5%
}

export interface StandardRevenueResult {
  subtotalCents: number;
  discountCents: number;
  taxableCents: number;
  taxCents: number;
  totalCents: number;
}

function assertNonNegativeInteger(value: number, field: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new Error(`${field} must be a non-negative integer`);
  }
}

export function calculateStandardRevenue(
  input: StandardRevenueInput,
): StandardRevenueResult {
  if (!input || !Array.isArray(input.items) || input.items.length === 0) {
    throw new Error('items must be a non-empty array');
  }

  const taxRateBps = input.taxRateBps ?? 0;
  assertNonNegativeInteger(taxRateBps, 'taxRateBps');

  let subtotalCents = 0;
  let discountCents = 0;

  for (const [index, item] of input.items.entries()) {
    assertNonNegativeInteger(item.unitPriceCents, `items[${index}].unitPriceCents`);
    assertNonNegativeInteger(item.quantity, `items[${index}].quantity`);
    assertNonNegativeInteger(item.discountCents ?? 0, `items[${index}].discountCents`);

    const lineSubtotal = item.unitPriceCents * item.quantity;
    const lineDiscount = item.discountCents ?? 0;

    if (lineDiscount > lineSubtotal) {
      throw new Error(`items[${index}].discountCents cannot exceed line subtotal`);
    }

    subtotalCents += lineSubtotal;
    discountCents += lineDiscount;
  }

  const taxableCents = subtotalCents - discountCents;
  const taxCents = Math.round((taxableCents * taxRateBps) / 10000);
  const totalCents = taxableCents + taxCents;

  return {
    subtotalCents,
    discountCents,
    taxableCents,
    taxCents,
    totalCents,
  };
}
```

