from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

TWOPLACES = Decimal("0.01")

class RevenueError(ValueError):
    pass


def _parse_amount(amount):
    if amount is None:
        raise RevenueError("amount is required")
    if isinstance(amount, bool):
        raise RevenueError("amount must be a valid number")
    try:
        parsed = Decimal(str(amount))
    except (InvalidOperation, ValueError):
        raise RevenueError("amount must be a valid number")
    if parsed < 0:
        raise RevenueError("amount must be >= 0")
    return parsed


def _parse_quantity(quantity):
    if quantity is None:
        raise RevenueError("quantity is required")
    if isinstance(quantity, bool):
        raise RevenueError("quantity must be a whole number")
    if isinstance(quantity, int):
        parsed = quantity
    elif isinstance(quantity, str):
        if quantity.strip() == "":
            raise RevenueError("quantity must be a whole number")
        try:
            parsed = int(quantity)
        except ValueError:
            raise RevenueError("quantity must be a whole number")
    else:
        raise RevenueError("quantity must be a whole number")

    if parsed < 0:
        raise RevenueError("quantity must be >= 0")
    return parsed


def calculate_standard_revenue(amount, quantity=1):
    parsed_amount = _parse_amount(amount)
    parsed_quantity = _parse_quantity(quantity)
    revenue = parsed_amount * parsed_quantity
    return revenue.quantize(TWOPLACES, rounding=ROUND_HALF_UP)

