```ts
// revenue.ts
export type RevenueInput = {
  unitPriceCents: number;
  quantity: number;
  discountCents?: number;
  refundedCents?: number;
};

export function calculateStandardRevenue(input: RevenueInput): number {
  const discount = input.discountCents ?? 0;
  const refunded = input.refundedCents ?? 0;

  if (!Number.isInteger(input.unitPriceCents) || input.unitPriceCents < 0) {
    throw new Error('unitPriceCents must be a non-negative integer');
  }
  if (!Number.isInteger(input.quantity) || input.quantity < 0) {
    throw new Error('quantity must be a non-negative integer');
  }
  if (!Number.isInteger(discount) || discount < 0) {
    throw new Error('discountCents must be a non-negative integer');
  }
  if (!Number.isInteger(refunded) || refunded < 0) {
    throw new Error('refundedCents must be a non-negative integer');
  }

  const gross = input.unitPriceCents * input.quantity;
  if (!Number.isSafeInteger(gross)) {
    throw new Error('gross revenue must be a safe integer');
  }

  const net = gross - discount - refunded;
  if (!Number.isSafeInteger(net)) {
    throw new Error('net revenue must be a safe integer');
  }

  return Math.max(0, net);
}
```

