+  priceCents?: number;
+  quantity: number;
+  refundable?: boolean;
+}
+
+export interface RevenueOrder {
+  items: RevenueItem[];
+  couponCents?: number;
+  refundedCents?: number;
+}
+
+function invalid(message: string): never {
+  throw new Error(`Invalid revenue input: ${message}`);
+}
+
+function isFiniteInteger(value: unknown): value is number {
+  return typeof value === 'number' && Number.isFinite(value) && Number.isInteger(value);
+}
+
+function normalizeAdjustment(value: unknown, field: 'couponCents' | 'refundedCents'): number {
+  if (value == null) return 0;
+  if (!isFiniteInteger(value)) {
+    invalid(`${field} must be a finite integer number of cents`);
+  }
+  return Math.max(0, value);
+}
+
+function lineItemSubtotal(item: RevenueItem, index: number): number {
+  if (!item || typeof item !== 'object') {
+    invalid(`items[${index}] must be an object`);
+  }
+
+  if (!isFiniteInteger(item.quantity) || item.quantity < 0) {
+    invalid(`items[${index}].quantity must be a non-negative finite integer`);
+  }
+
+  const hasPriceCents = item.priceCents !== undefined;
+  const hasPrice = item.price !== undefined;
+
+  if (hasPriceCents) {
+    if (!isFiniteInteger(item.priceCents) || item.priceCents < 0) {
+      invalid(`items[${index}].priceCents must be a non-negative finite integer`);
+    }
+    return item.priceCents * item.quantity;
+  }
+
+  // Backward compatibility: support legacy { price, quantity } callers.
+  // Legacy price is treated as a major-unit whole number and converted to cents.
+  if (hasPrice) {
+    if (!isFiniteInteger(item.price) || item.price < 0) {
+      invalid(`items[${index}].price must be a non-negative finite integer`);
+    }
+    return item.price * 100 * item.quantity;
+  }
+
+  invalid(`items[${index}] must include priceCents or price`);
+}
+
+/**
+ * Returns recognized revenue in cents.
+ * Standard path rules:
+ * - sum line items using integer cents
+ * - subtract coupon discount once per order
+ * - subtract already-refunded amount
+ * - never return a negative total
+ *
+ * Compatibility:
+ * - preferred item field is priceCents
+ * - legacy price is still accepted as a whole major-unit integer and converted to cents
+ */
+export function calculateRevenue(order: RevenueOrder): number {
+  if (!order || typeof order !== 'object' || !Array.isArray(order.items)) {
+    invalid('order.items must be an array');
+  }
+
+  const gross = order.items.reduce((sum, item, index) => {
+    return sum + lineItemSubtotal(item, index);
+  }, 0);
+
+  const couponCents = normalizeAdjustment(order.couponCents, 'couponCents');
+  const refundedCents = normalizeAdjustment(order.refundedCents, 'refundedCents');
+
+  return Math.max(0, gross - couponCents - refundedCents);
+}
