+
+function normalizeLegacyAdjustment(value: unknown, field: 'coupon' | 'refunded'): number {
+  if (value == null) return 0;
+  if (!isFiniteInteger(value)) {
+    invalid(`${field} must be a finite integer`);
+  }
+  return Math.max(0, value);
+}
+
+function normalizeCentAdjustment(value: unknown, field: 'couponCents' | 'refundedCents'): number {
+  if (value == null) return 0;
+  if (!isFiniteInteger(value)) {
+    invalid(`${field} must be a finite integer number of cents`);
+  }
+  return Math.max(0, value);
+}
+
+function legacyLineItemSubtotal(item: RevenueItem, index: number): number {
+  validateItemObject(item, index);
+  if (item.price === undefined) {
+    invalid(`items[${index}].price is required for legacy calculateRevenue callers`);
+  }
+  if (!isFiniteInteger(item.price) || item.price < 0) {
+    invalid(`items[${index}].price must be a non-negative finite integer`);
+  }
+  return item.price * item.quantity;
+}
+
+function centLineItemSubtotal(item: RevenueItem, index: number): number {
+  validateItemObject(item, index);
+  if (item.priceCents === undefined) {
+    invalid(`items[${index}].priceCents is required for calculateRevenueCents callers`);
+  }
+  if (!isFiniteInteger(item.priceCents) || item.priceCents < 0) {
+    invalid(`items[${index}].priceCents must be a non-negative finite integer`);
+  }
+  return item.priceCents * item.quantity;
+}
+
+/**
+ * Backward-compatible legacy API.
+ *
+ * Returns recognized revenue in the same units as legacy `price` inputs.
+ * This preserves historical behavior for existing callers.
+ */
+export function calculateRevenue(order: RevenueOrder): number {
+  validateOrder(order);
+
+  const gross = order.items.reduce((sum, item, index) => {
+    return sum + legacyLineItemSubtotal(item, index);
+  }, 0);
+
+  const coupon = normalizeLegacyAdjustment(order.coupon, 'coupon');
+  const refunded = normalizeLegacyAdjustment(order.refunded, 'refunded');
+
+  return Math.max(0, gross - coupon - refunded);
