+  validateOrder(order);
+
+  const gross = order.items.reduce((sum, item, index) => {
+    return sum + centLineItemSubtotal(item, index);
+  }, 0);
+
+  const couponCents = normalizeCentAdjustment(order.couponCents, 'couponCents');
+  const refundedCents = normalizeCentAdjustment(order.refundedCents, 'refundedCents');
+
+  return Math.max(0, gross - couponCents - refundedCents);
+}
