+export class RevenueValidationError extends Error {
+  constructor(message: string) {
+    super(message);
+    this.name = 'RevenueValidationError';
+  }
+}
+
+function assertFiniteNumber(value: number, field: string): void {
+  if (!Number.isFinite(value)) {
+    throw new RevenueValidationError(`${field} must be a finite number`);
+  }
+}
+
+export function calculateRevenue(amount: number, taxRate: number): number {
+  assertFiniteNumber(amount, 'amount');
+  assertFiniteNumber(taxRate, 'taxRate');
+
+  if (amount < 0) {
+    throw new RevenueValidationError('amount must be greater than or equal to 0');
+  }
+
+  if (taxRate < 0) {
+    throw new RevenueValidationError('taxRate must be greater than or equal to 0');
+  }
+
+  return amount + amount * taxRate;
+}
+
+export function calculateRevenueSafe(
+  amount: number,
+  taxRate: number,
+): { ok: true; value: number } | { ok: false; error: string } {
+  try {
+    return { ok: true, value: calculateRevenue(amount, taxRate) };
+  } catch (error) {
+    if (error instanceof RevenueValidationError) {
+      return { ok: false, error: error.message };
+    }
+    throw error;
+  }
+}
