+): number {
   const baseAmount = Number.isFinite(amount) ? amount : 0;
   const normalizedTaxRate = Number.isFinite(taxRate) ? taxRate : 0;
   const normalizedDiscount = Number.isFinite(discount) ? discount : 0;

